INSERT INTO "careers_responsibilities" ("_order","_parent_id","id","text") VALUES(1,8,'6a27884535954f752e494dc4','{"root":{"type":"root","format":"","indent":0,"version":1,"direction":null,"children":[{"type":"paragraph","format":"","indent":0,"version":1,"direction":null,"children":[{"type":"text","text":"- Tối ưu toàn bộ funnel chuyển đổi trên website: theo dõi hành vi, phân tích drop-off, đề xuất cải tiến. - Lên kế hoạch và triển khai A/B testing: layout, UX flow, copywrite, visual triggers… - Phối hợp với team thiết kế để tối ưu UI/UX, bảo đảm hiệu ứng thị giác thúc đẩy hành động (CTA clarity – visual hierarchy). - Viết micro-copy & conversion copy cho landing pages, onboarding flow, CRM touchpoints. - Theo dõi các chỉ số cốt lõi (CR,AOV, LTV, bounce rate…), rút insight và đề xuất chiến lược tăng trưởng. - Đóng góp vào roadmap cải thiện chuyển đổi dài hạn: từ web, CRM đến loyalty và referral. - Xây dựng và vận hành loyalty platform (tier benefits, reward logic, engagement loop). - Thực hiện các công việc khác theo yêu cầu của quản lý. ","detail":0,"format":0,"mode":"normal","style":"","version":1}]}]}}');
INSERT INTO "careers_responsibilities" ("_order","_parent_id","id","text") VALUES(2,8,'6a27887035954f752e494dc6','{"root":{"type":"root","format":"","indent":0,"version":1,"direction":null,"children":[{"type":"paragraph","format":"","indent":0,"version":1,"direction":null,"children":[{"type":"text","text":"- Thực hiện các công việc khác theo yêu cầu của quản lý. ","detail":0,"format":0,"mode":"normal","style":"","version":1}]}]}}');
INSERT INTO "careers_responsibilities" ("_order","_parent_id","id","text") VALUES(1,11,'6a27d876bf5af030db9f98fe','{"root":{"children":[{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Kỹ năng/ Chuyên môn - Tốt nghiệp Đại học chuyên ngành Marketing, Thương mại điện tử, Kinh doanh hoặc các ngành liên quan.  - Có từ 1 năm kinh nghiệm ở vị trí CRO, E-commerce Optimization, UX/Data Analyst hoặc các vị trí liên quan.  - Có kinh nghiệm làm việc với Claude code hoặc claude design - Có kinh nghiệm làm product page , landing page : Funnelish, Gempage, custom HTML ,  - Hiểu rõ funnel chuyển đổi, hành vi người dùng trên website và các chỉ số liên quan đến conversion.  - Có kinh nghiệm làm việc với UI/UX, A/B testing hoặc tối ưu conversion trong môi trường E-commerce.  - Thành thạo các công cụ phân tích như GA4, Hotjar/Clarity hoặc các công cụ tương đương.  - Có tư duy phân tích dữ liệu, khả năng đọc insight và đề xuất phương án cải thiện hiệu quả.  - Điểm cộng:   - Có hiểu biết về copywriting phục vụ chuyển đổi (CTA, micro-copy, offer framing…).    - Biết sử dụng các công cụ chỉnh sửa prototype như Figma/FigJam/Canva là lợi thế.    - Có kinh nghiệm trong lĩnh vực POD, E-commerce US, CRM, loyalty hoặc retention là lợi thế. Thái độ/Giá trị - Chủ động, ham học hỏi, có tinh thần nghiên cứu và liên tục cải tiến. - Có tư duy logic, khả năng giải quyết vấn đề và xử lý tình huống linh hoạt. - Kỹ năng giao tiếp rõ ràng, phối hợp tốt với các bộ phận liên quan. - Cẩn thận, trách nhiệm, có khả năng làm việc độc lập và làm việc nhóm hiệu quả.","type":"text","version":1}],"direction":null,"format":"","indent":0,"type":"paragraph","version":1,"textFormat":0,"textStyle":""}],"direction":null,"format":"","indent":0,"type":"root","version":1}}');
