INSERT INTO "_careers_v_version_benefits" ("_order","_parent_id","id","text","_uuid") VALUES(1,21,26,'{"root":{"children":[{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Thu nhập: - Thu nhập: 8-12 triệu + Bonus (theo performance) - Thời gian thử việc: 2 tháng (85% lương chính thức) - Review lương 2 lần/ năm  Phúc lợi khác: - Đóng BHXH, BHYT, BHTN theo quy định khi là nhân viên chính thức. - Lương tháng 13, thưởng lễ, Tết và các hoạt động nội bộ như happy hours, KICK-OFF theo quý. - Môi trường làm việc năng động, sáng tạo và thân thiện. - Cơ hội học hỏi, phát triển kỹ năng và lộ trình thăng tiến rõ ràng. - Chi tiết các quyền lợi sẽ được trao đổi cụ thể trong quá trình phỏng vấn.","type":"text","version":1}],"direction":null,"format":"","indent":0,"type":"paragraph","version":1,"textFormat":0,"textStyle":""}],"direction":null,"format":"","indent":0,"type":"root","version":1}}','6a27d886bf5af030db9f9900');
